class PanelQuad
{
  struct VTable
  {
    char prefix[24];
    short turn_on_adjust;
    short gap;
    void (*turn_on)(void *, bool);
  };
  char prefix[404];
  VTable *vtable;

public:
  void TurnOn(bool enabled)
  {
    VTable *table = vtable;
    table->turn_on((char *)this + table->turn_on_adjust, enabled);
  }
};

class PanelFile
{
public:
  PanelQuad *GetPointer(const char *name);
};

class SpecialMeter
{
public:
  void SetFillage(float amount);
};

class IGOWidget
{
protected:
  int display;
  struct VTable
  {
    char prefix[16];
    short set_display_adjust;
    short gap;
    void (*set_display)(void *, bool);
  } *vtable;

public:
  void SetDisplay(bool enabled)
  {
    VTable *table = vtable;
    table->set_display((char *)this + table->set_display_adjust, enabled);
  }
};

class SplitMeterWidget : public IGOWidget
{
  enum { NUM_FRAMES = 3 };
  SpecialMeter *meter;
  PanelQuad *colorPQ;
  PanelQuad *framePQs[NUM_FRAMES];

public:
  void Init(PanelFile &panel, SpecialMeter *specialMeter, const bool left);
};

__asm__(".equ SetFillage__12SpecialMeterf, 0x00251028");
__asm__(".equ GetPointer__9PanelFilePCc, 0x00152F88");

void SplitMeterWidget::Init(PanelFile & panel, SpecialMeter * specialMeter, const bool left)
{
	meter = specialMeter;
	meter->SetFillage(0.0f);

	if (left)
	{
		framePQs[0] = panel.GetPointer("left_meter_01");
		framePQs[1] = panel.GetPointer("left_meter_03");
		framePQs[2] = panel.GetPointer("left_meter_04");
		colorPQ = panel.GetPointer("left_meter_02");
	}
	else
	{
		framePQs[0] = panel.GetPointer("right_meter_01");
		framePQs[1] = panel.GetPointer("right_meter_03");
		framePQs[2] = panel.GetPointer("right_meter_04");
		colorPQ = panel.GetPointer("right_meter_02");
	}

	for (int i = 0; i < NUM_FRAMES; i++)
		framePQs[i]->TurnOn(true);
	colorPQ->TurnOn(true);

	SetDisplay(true);
}
